        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        import math

def get_divisors(n):
    n = abs(n)
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def generator(rng):
    while True:
        # Choose underlying integer parameters a and b
        b = rng.randint(-12, 12)

        # Find divisors of b^2+1 to select 'a' from, ensuring a | (b^2+1)
        b_sq_plus_1 = b*b + 1
        divs = get_divisors(b_sq_plus_1)
        a = rng.choice(divs)

        # Avoid the exact polynomial from the seed problem (k^2-k+1)
        if a == 1 and b == 0:
            continue

        # n should not be too small for the sum to be interesting
        n = rng.randint(3, 25)

        # The multiplier C=an makes it harder to guess its relation to n
        C = a * n

        # Calculate the coefficients of the polynomial P(k)
        c2 = a
        c1 = 2 * b - a
        c0 = (b*b - a*b + 1) // a

        # Ensure coefficients are not excessively large for presentation
        if abs(c1) > 150 or abs(c0) > 150:
            continue

        # Ensure the answer is not zero, which can be a trivial guess
        answer = b*b + 1 + a*b*n
        if answer == 0:
            continue

        return {
            "c2": c2,
            "c1": c1,
            "c0": c0,
            "n": n,
            "C": C,
        }

        def verifier(assign):
    c2 = assign['c2']
    c1 = assign['c1']
    c0 = assign['c0']
    n = assign['n']
    C = assign['C']

    # Verify types
    if not all(isinstance(v, int) for v in [c2, c1, c0, n, C]):
        return False, "All parameters must be integers."

    # Re-derive the hidden parameters 'a' and 'b' to check for consistency
    if c2 <= 0 or n <= 0:
        return False, "c2 and n must be positive."
    a = c2

    # From c1 = 2b - a, we get 2b = c1 + a. This implies c1+a must be even.
    if (c1 + a) % 2 != 0:
        return False, "c1+a must be even for b to be an integer."
    b = (c1 + a) // 2

    # Check consistency of the generated parameters
    if C != a * n:
        return False, "C must be equal to a*n."

    if (b*b + 1) % a != 0:
        return False, "a must be a divisor of b^2+1."

    if c0 * a != (b*b - a*b + 1):
        return False, "c0 is inconsistent with a and b."

    # Avoid the seed problem's polynomial, which is a trivial case of this family
    if a == 1 and b == 0:
        return False, "This corresponds to the seed problem's polynomial."

    # Calculate the theoretical answer
    answer = b*b + 1 + a*b*n

    if answer == 0:
        return False, "The answer should not be zero."

    return True, answer


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
